#include <algorithm>
#include <iostream>
#include <vector>

using namespace std;

signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);
    string base = "LIT";
    int t; cin >> t;
    while (t--) {
        int n; string s;
        cin >> n >> s;
        if (count(s.begin(), s.end(), s[0]) == n) {
            cout << -1 << '\n';
        } else {
            vector <int> ans;
            while (true) {
                vector <pair<int, char>> cnt;
                for (auto i : base) cnt.push_back(make_pair(count(s.begin(), s.end(), i), i));
                sort(cnt.begin(), cnt.end());
                if (cnt[0].first == cnt[1].first && cnt[1].first == cnt[2].first) break;

                auto op = [&] (int i) -> void {
                    string z = base; z.erase(find(z.begin(), z.end(), s[i])); z.erase(find(z.begin(), z.end(), s[i + 1]));
                    ans.push_back(i);
                    s = s.substr(0, i + 1) + z[0] + s.substr(i + 1);
                };

                bool done = false;
                for (int i = 0; i < s.size() - 1; ++i) {
                    if (s[i] == s[i + 1]) continue;
                    if (s[i] != cnt[0].second && s[i + 1] != cnt[0].second) {
                        op(i); 
                        done = true;
                        break;
                    }
                }

                if (done) continue;

                for (int i = 0; i < s.size() - 1; ++i) {
                    if (s[i] == s[i + 1]) continue;
                    if (s[i] == cnt[2].second) {
                        op(i); op(i + 1); op(i); op(i + 2); break;
                    } else if (s[i + 1] == cnt[2].second) {
                        op(i); op(i); op(i + 1); op(i + 3); break;
                    }
                }
            }

            cout << ans.size() << '\n';
            for (auto i : ans) cout << i + 1 << '\n';
        }
    }
}

#include <vector>
#include <string>
#include <iostream>
#include <set>
#include <map>
using namespace std;

vector<char> a = {'L', 'I', 'T'};

int main() {
    int t; cin >> t;
    while (t--) {
        int n; cin >> n;
        string s; cin >> s;
        set<char> se;
        for (auto u : s) se.insert(u);
        if (se.size() == 1) {
            cout << -1 << endl;
            continue;
        }
        vector<int> ans;
        map<char, int> mp;
        for (auto u : s) {
            mp[u]++;
        }
        auto func = [&](int i) {
            for (auto u : a) {
                if (s[i] != u && s[i + 1] != u) return u;
            }
            return '$';
        };
        while (max({mp['L'], mp['I'], mp['T']}) != min({mp['L'], mp['I'], mp['T']})) {
            int mn = min({mp['L'], mp['I'], mp['T']});
            int mx = max({mp['L'], mp['I'], mp['T']});
            int ok = 0;
            for (int i = 0; i < s.size() - 1; i++) {
                char x = func(i);
                if (s[i] != s[i + 1] && mp[x] == mn) {
                    mp[x]++;
                    ok = 1;
                    s.insert(s.begin() + i + 1, x);
                    ans.push_back(i);
                    break;
                }
            }
            if (!ok) {
                for (int i = 0; i < s.size() - 1; i++) {
                    char x = func(i);
                    if (s[i] != s[i + 1] && mp[x] == mx) {
                        mp[x]++;
                        s.insert(s.begin() + i + 1, x);
                        ans.push_back(i);
                        ok = 1;
                        break;
                    }
                }
            }
        }
        cout << ans.size() << endl;
        for (auto u : ans) {
            cout << u + 1 << endl;
        }
    }
}
